}), d = "1.9.2", f = {
	debug: 0,
	info: 1,
	warn: 2,
	error: 3
}, p = { ...console }, m = p.log, h = p.warn, g = p.error, _ = () => f.warn, v = (e) => {
	let t = _();
	return f[e] >= t;
};
console.debug = (...e) => {
	v("debug") && m(`[${d}]`, ...e);
}, console.log = (...e) => {
	v("info") && m(`[${d}]`, ...e);
}, console.info = (...e) => {
	v("info") && m(`[${d}]`, ...e);
}, console.warn = (...e) => {
	v("warn") && h(`[${d}]`, ...e);
}, console.error = (...e) => {
	v("error") && g(`[${d}]`, ...e);
};
